function Get-SidebarHtml($currentSlug) {
    $others = $articles | Where-Object { $_.slug -ne $currentSlug } | Select-Object -First 6
    $items = ($others | ForEach-Object {
        $img = "../assets/à¸ à¸²à¸žà¸šà¸—à¸„à¸§à¸²à¸¡/$($_.image)"
        @"
            <li>
              <a class="article-sidebar-link" href="$($_.slug).html">
                <img src="$img" alt="" width="120" height="75" loading="lazy" decoding="async">
                <span>$($_.title)</span>
              </a>
            </li>
"@
    }) -join "`n"
    return @"
